from flask import Flask, render_template_string, request, session, redirect, url_for, jsonify
import psycopg2
import psycopg2.extras
import psycopg2.extensions
import os
import datetime
import sqlite3
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY") or os.urandom(32)
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"

# ==============================================
# POSTGRESQL CONFIGURATION
# ==============================================
# Option A: set DATABASE_URL, e.g. postgresql://user:password@localhost:5432/it_service_system
# Option B: set DB_HOST / DB_PORT / DB_NAME / DB_USER / DB_PASSWORD
DATABASE_URL = os.environ.get("DATABASE_URL")
DB_CONFIG = {
    "host": os.environ.get("DB_HOST", "localhost"),
    "port": os.environ.get("DB_PORT", "5432"),
    "dbname": os.environ.get("DB_NAME", "it_service_system"),
    "user": os.environ.get("DB_USER", "postgres"),
    "password": os.environ.get("DB_PASSWORD", ""),
}

# Return TIMESTAMP columns as 'YYYY-MM-DD HH:MM:SS' strings (same as SQLite did),
# so templates like {{ t.submitted_at[:10] }} keep working.
def _timestamp_to_str(value, cur):
    return value[:19] if value else None

psycopg2.extensions.register_type(
    psycopg2.extensions.new_type(psycopg2.extensions.PYDATETIME.values,
                                 "TIMESTAMP_STR", _timestamp_to_str))

# ==============================================
# DATABASE CONNECTION (PostgreSQL with automatic SQLite fallback)
# ==============================================
DB_BACKEND = None  # set by _detect_backend(): 'postgres' or 'sqlite'
DB_SQLITE_PATH = os.environ.get("DB_SQLITE_PATH", "it_service_system.db")

def _adapt_sqlite_sql(sql):
    """Translate this app's PostgreSQL-style SQL into SQLite-compatible SQL.
    Only the constructs actually used by this app are translated."""
    sql = sql.replace('%s', '?')                                    # psycopg2 placeholder -> sqlite qmark
    sql = sql.replace('SERIAL PRIMARY KEY', 'INTEGER PRIMARY KEY AUTOINCREMENT')
    # Longest / most-specific patterns FIRST, before shorter ones rewrite their pieces.
    sql = sql.replace("date_trunc('month', NOW() AT TIME ZONE 'Asia/Manila') - INTERVAL '11 months'",
                      "datetime('now','+8 hours','start of month','-11 months')")
    sql = sql.replace("NOW() AT TIME ZONE 'Asia/Manila'", "datetime('now','+8 hours')")
    sql = sql.replace("TO_CHAR(submitted_at, 'YYYY-MM')", "strftime('%Y-%m', submitted_at)")
    sql = sql.replace("TO_CHAR(submitted_at, 'YYYY')", "strftime('%Y', submitted_at)")
    return sql

class _SQLiteCursor:
    """Wraps a sqlite3.Cursor so the rest of the app (written for psycopg2) works unchanged."""
    def __init__(self, cur):
        self._cur = cur
    def execute(self, sql, params=None):
        sql = _adapt_sqlite_sql(sql)
        if params is None:
            return self._cur.execute(sql)
        return self._cur.execute(sql, params)
    def executemany(self, sql, seq):
        return self._cur.executemany(_adapt_sqlite_sql(sql), seq)
    def fetchone(self): return self._cur.fetchone()
    def fetchall(self): return self._cur.fetchall()
    @property
    def rowcount(self): return self._cur.rowcount
    @property
    def lastrowid(self): return self._cur.lastrowid
    def close(self): return self._cur.close()
    def __iter__(self): return iter(self._cur)

class _SQLiteConn:
    def __init__(self, conn):
        self._conn = conn
    def cursor(self): return _SQLiteCursor(self._conn.cursor())
    def commit(self): return self._conn.commit()
    def rollback(self): return self._conn.rollback()
    def close(self): return self._conn.close()

def _detect_backend():
    """Try PostgreSQL first. If it is unreachable, fall back to SQLite.
    The user's PostgreSQL database is NEVER modified."""
    global DB_BACKEND
    try:
        if DATABASE_URL:
            t = psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.DictCursor)
        else:
            t = psycopg2.connect(cursor_factory=psycopg2.extras.DictCursor, **DB_CONFIG)
        t.close()
        DB_BACKEND = 'postgres'
        print("[DB] Backend: PostgreSQL")
    except Exception as e:
        DB_BACKEND = 'sqlite'
        print(f"[DB] PostgreSQL unavailable ({e}) -> falling back to SQLite file: {DB_SQLITE_PATH}")
        print("[DB] Your PostgreSQL database is NOT modified. Fix credentials/host and restart to use it again.")

def get_db():
    if DB_BACKEND == 'sqlite':
        try:
            conn = sqlite3.connect(DB_SQLITE_PATH)
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA foreign_keys = ON")
            return _SQLiteConn(conn)
        except Exception as e:
            print(f"[DB] SQLite Error: {e}")
            return None
    # PostgreSQL (original behaviour — your database is untouched)
    try:
        if DATABASE_URL:
            return psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.DictCursor)
        return psycopg2.connect(cursor_factory=psycopg2.extras.DictCursor, **DB_CONFIG)
    except Exception as e:
        print(f"[DB] PostgreSQL Error: {e}")
        return None

# ==============================================
# CREATE TABLES
# ==============================================
def init_db():
    conn = get_db()
    if not conn: return
    cur = conn.cursor()

    cur.execute("""
    CREATE TABLE IF NOT EXISTS users (
        id SERIAL PRIMARY KEY,
        full_name TEXT NOT NULL,
        email TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'requestor',
        department TEXT,
        contact_number TEXT,
        is_active INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila')
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS tickets (
        id SERIAL PRIMARY KEY,
        reference_no TEXT UNIQUE NOT NULL,
        requestor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        department TEXT NOT NULL,
        contact_number TEXT NOT NULL,
        equipment_type TEXT NOT NULL,
        brand_model TEXT,
        serial_property_no TEXT,
        location_room TEXT NOT NULL,
        problem_description TEXT NOT NULL,
        priority TEXT NOT NULL DEFAULT 'medium',
        status TEXT NOT NULL DEFAULT 'pending_admin',
        assigned_to INTEGER REFERENCES users(id) ON DELETE SET NULL,
        scheduled_date TEXT,
        work_done TEXT,
        parts_replaced TEXT,
        resolution_notes TEXT,
        requestor_feedback TEXT,
        admin_approved INTEGER DEFAULT 0,
        staff_approved INTEGER DEFAULT 0,
        submitted_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila'),
        updated_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila'),
        completed_at TIMESTAMP,
        approved_at TIMESTAMP
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS status_history (
        id SERIAL PRIMARY KEY,
        ticket_id INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
        status TEXT NOT NULL,
        notes TEXT,
        updated_by INTEGER NOT NULL REFERENCES users(id),
        updated_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila')
    )""")

    cur.execute("""
    CREATE TABLE IF NOT EXISTS notifications (
        id SERIAL PRIMARY KEY,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        ticket_id INTEGER REFERENCES tickets(id) ON DELETE CASCADE,
        message TEXT NOT NULL,
        is_read INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila')
    )""")
    cur.execute("""
    CREATE TABLE IF NOT EXISTS csm_responses (
        id SERIAL PRIMARY KEY,
        ticket_id INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
        client_type TEXT, sex TEXT, age TEXT, region TEXT, service_availed TEXT,
        cc1 TEXT, cc2 TEXT, cc3 TEXT,
        sqd0 TEXT, sqd1 TEXT, sqd2 TEXT, sqd3 TEXT, sqd4 TEXT,
        sqd5 TEXT, sqd6 TEXT, sqd7 TEXT, sqd8 TEXT,
        suggestions TEXT, email TEXT,
        submitted_at TIMESTAMP DEFAULT (NOW() AT TIME ZONE 'Asia/Manila')
    )""")

    conn.commit()
    conn.close()

_detect_backend()
init_db()

# ==============================================
# PHILIPPINE TIME — UTC+8
# ==============================================
def ph_now():
    return datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8)))

def ph_now_str():
    return ph_now().strftime('%Y-%m-%d %H:%M:%S')

# ==============================================
# REFERENCE NUMBER: REQ-2026-00001
# ==============================================
def generate_ref_no():
    now = ph_now()
    year = now.year
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) FROM tickets WHERE TO_CHAR(submitted_at, 'YYYY') = %s", (str(year),))
    count = cur.fetchone()[0] + 1
    conn.close()
    return f"REQ-{year}-{count:05d}"

# ==============================================
# DECORATORS
# ==============================================
def login_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        # Requester must accept Terms & Conditions once per login session
        if session.get('role') == 'requestor' and not session.get('terms_accepted'):
            if request.endpoint not in ('terms', 'logout'):
                return redirect(url_for('terms'))
        return f(*args, **kwargs)
    return wrap

def staff_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        if session.get('role') != 'staff':
            return " Access Denied — IT Staff Only", 403
        return f(*args, **kwargs)
    return wrap

def admin_required(f):
    from functools import wraps
    @wraps(f)
    def wrap(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        if session.get('role') != 'admin':
            return " Access Denied — Admin Only", 403
        return f(*args, **kwargs)
    return wrap

